#include <LedControl.h>
#include <ThreeWire.h>
#include <RtcDS1302.h>

// ================= НАСТРОЙКА ПИНОВ =================
// DS1302 (RTC)
const int RTC_RST_PIN = 2; // CE
const int RTC_DAT_PIN = 3; // IO
const int RTC_CLK_PIN = 4; // SCLK

// MAX7219 (Матрица)
const int DIN_PIN = 11;
const int CS_PIN  = 10;
const int CLK_PIN = 13;
const int MATRIX_COUNT = 4; // Количество модулей 8x8

// ================= ОБЪЕКТЫ =================
ThreeWire myWire(RTC_DAT_PIN, RTC_CLK_PIN, RTC_RST_PIN);
RtcDS1302<ThreeWire> Rtc(myWire);

// LedControl(DIN, CLK, CS, Количество_модулей)
LedControl lc = LedControl(DIN_PIN, CLK_PIN, CS_PIN, MATRIX_COUNT);

// ================= ШРИФТ ЦИФР (5x7) =================
// Битовые маски для цифр 0-9. Каждая цифра занимает 5 столбцов.
const byte digits[10][5] = {
  {0x3E, 0x51, 0x49, 0x45, 0x3E}, // 0
  {0x00, 0x42, 0x7F, 0x40, 0x00}, // 1
  {0x42, 0x61, 0x51, 0x49, 0x46}, // 2
  {0x21, 0x41, 0x45, 0x4B, 0x31}, // 3
  {0x18, 0x14, 0x12, 0x7F, 0x10}, // 4
  {0x27, 0x45, 0x45, 0x45, 0x39}, // 5
  {0x3C, 0x4A, 0x49, 0x49, 0x30}, // 6
  {0x01, 0x71, 0x09, 0x05, 0x03}, // 7
  {0x36, 0x49, 0x49, 0x49, 0x36}, // 8
  {0x06, 0x49, 0x49, 0x29, 0x1E}  // 9
};

void setup() {
  Serial.begin(9600);

  // --- Инициализация RTC ---
  Rtc.Begin();

  // ВАЖНО: Раскомментируйте строку ниже ОДИН РАЗ, чтобы установить время
  // на момент компиляции скетча. Потом закомментируйте обратно.
  // Rtc.SetDateTime(RtcDateTime(__DATE__, __TIME__));

  // Проверка валидности времени и запуск часов
  if (!Rtc.IsDateTimeValid()) {
    Serial.println("RTC lost confidence in the DateTime!");
    Rtc.SetDateTime(RtcDateTime(__DATE__, __TIME__));
  }
  if (Rtc.GetIsWriteProtected()) {
    Rtc.SetIsWriteProtected(false);
  }
  if (!Rtc.GetIsRunning()) {
    Rtc.SetIsRunning(true);
  }

  // --- Инициализация матриц ---
  for (int i = 0; i < MATRIX_COUNT; i++) {
    lc.shutdown(i, false); // Выход из спящего режима
    lc.setIntensity(i, 8); // Яркость (0-15)
    lc.clearDisplay(i);    // Очистка
  }
}

void loop() {
  RtcDateTime now = Rtc.GetDateTime();

  int hour = now.Hour();
  int minute = now.Minute();

  // Вывод времени на матрицу
  displayTime(hour, minute);

  delay(1000); // Обновление раз в секунду
}

// Функция для отрисовки времени на 4 модулях (32x8)
void displayTime(int hour, int minute) {
  // Очищаем экран перед отрисовкой (чтобы не было "мусора")
  for (int i = 0; i < MATRIX_COUNT; i++) {
    lc.clearDisplay(i);
  }

  // Разбиваем время на цифры
  int h1 = hour / 10;   // Десятки часов
  int h2 = hour % 10;   // Единицы часов
  int m1 = minute / 10; // Десятки минут
  int m2 = minute % 10; // Единицы минут

  // Раскладка на 4 модуля (32 столбца):
  // Модуль 0 (столбцы 0-7): Десятки часов + пробел + начало единиц
  // Модуль 1 (столбцы 8-15): Окончание единиц часов + разделитель + начало минут
  // Модуль 2 (столбцы 16-23): Десятки минут + пробел + начало единиц
  // Модуль 3 (столбцы 24-31): Окончание единиц минут

  // Рисуем цифры (каждая цифра 5 пикселей шириной)
  // Позиции подобраны так, чтобы цифры не обрезались на стыках модулей.

  drawDigit(0, 0, h1);      // Модуль 0, начало
  drawDigit(0, 7, h2);      // Модуль 0, конец / Модуль 1, начало (переход через границу)

  // Разделитель (двоеточие) на модуле 1
  drawColon(1);

  drawDigit(1, 10, m1);     // Модуль 1, продолжение
  drawDigit(1, 17, m2);     // Модуль 2/3 (переход)
}

// Вспомогательная функция для установки одного пикселя
void setPixel(int x, int y, bool state) {
  if (x < 0 || x >= 32 || y < 0 || y >= 8) return; // Защита от выхода за границы
  int module = x / 8;
  int col = x % 8;
  // В библиотеке LedControl строки идут сверху вниз, но матрицы могут быть перевернуты.
  // Если изображение перевернуто, используйте (7 - y) вместо y.
  lc.setLed(module, y, col, state); 
}

// Отрисовка одной цифры
void drawDigit(int startX, int startY, int digit) {
  // Ограничиваем digit в пределах 0-9
  if (digit < 0 || digit > 9) return;

  for (int col = 0; col < 5; col++) {
    byte bits = digits[digit][col];
    for (int row = 0; row < 7; row++) {
      // Проверяем бит (бит 0 - верхний или нижний, зависит от ориентации)
      if (bits & (1 << row)) { 
        setPixel(startX + col, startY + row, true);
      }
    }
  }
}

// Отрисовка двоеточия
void drawColon(int module) {
  // Рисуем две точки на модуле (примерно по центру)
  // Координаты подобраны для модуля 1 (столбцы 8-15 глобально)
  // Точка 1
  setPixel(module * 8 + 2, 2, true);
  // Точка 2
  setPixel(module * 8 + 2, 5, true);
}
